#include "config.h"
#include "baldr/graphreader.h"
#include <iostream>
#include <iomanip>
int main(int argc,char**argv){using namespace valhalla::baldr;GraphReader r(valhalla::config(argv[1]).get_child("mjolnir"));double w=std::stod(argv[2]),s=std::stod(argv[3]),e=std::stod(argv[4]),n=std::stod(argv[5]);for(auto id:r.GetTileSet()){auto t=r.GetGraphTile(id);for(uint32_t j=0;j<t->header()->nodecount();++j){auto node=t->node(j);auto ll=node->latlng(t->header()->base_ll());if(ll.lng()<w||ll.lng()>e||ll.lat()<s||ll.lat()>n)continue;for(uint32_t i=node->edge_index();i<node->edge_index()+node->edge_count();++i){auto edge=t->directededge(i);if(edge->is_shortcut())continue;auto info=t->edgeinfo(edge);auto shape=info.shape();if(!edge->forward())std::reverse(shape.begin(),shape.end());std::cout<<"{\"edge\":"<<GraphId(id.tileid(),id.level(),i).value<<",\"way\":"<<info.wayid()<<",\"startnode\":"<<GraphId(id.tileid(),id.level(),j).value<<",\"endnode\":"<<edge->endnode().value<<",\"node_bike\":"<<bool(node->access()&kBicycleAccess)<<",\"bike\":"<<bool(edge->forwardaccess()&kBicycleAccess)<<",\"reverse_bike\":"<<bool(edge->reverseaccess()&kBicycleAccess)<<",\"forward\":"<<edge->forward()<<",\"class\":"<<int(edge->classification())<<",\"use\":"<<int(edge->use())<<",\"length\":"<<edge->length()<<",\"names\":[";bool comma=false;for(auto name:info.GetNames()){if(comma)std::cout<<',';comma=true;std::cout<<std::quoted(name);}std::cout<<"],\"shape\":[";comma=false;for(auto xy:shape){if(comma)std::cout<<',';comma=true;std::cout<<std::setprecision(9)<<'['<<xy.lat()<<','<<xy.lng()<<']';}std::cout<<"]}\n";}}}}
